#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string recipe;
    cin >> recipe;

    ll nb, ns, nc;
    cin >> nb >> ns >> nc;

    ll pb, ps, pc;
    cin >> pb >> ps >> pc;

    ll r;
    cin >> r;

    ll numB = 0, numS = 0, numC = 0;
    for (char ingredient : recipe) {
        if (ingredient == 'B') ++numB;
        else if (ingredient == 'S') ++numS;
        else ++numC;
    }

    ll left = 0, right = 1000000000000LL;
    ll answer = 0;

    while (left <= right) {
        ll middle = left + (right - left) / 2;

        ll requiredB = max(numB * middle - nb, 0LL);
        ll requiredS = max(numS * middle - ns, 0LL);
        ll requiredC = max(numC * middle - nc, 0LL);

        ll cost = requiredB * pb + requiredS * ps + requiredC * pc;

        if (cost <= r) {
            answer = middle;
            left = middle + 1;
        } else {
            right = middle - 1;
        }
    }

    cout << answer << '\n';
    return 0;
}

