#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string recipe;
    cin >> recipe;

    ll nb, ns, nc;
    cin >> nb >> ns >> nc;

    ll pb, ps, pc;
    cin >> pb >> ps >> pc;

    ll r;
    cin >> r;

    ll numB = count(recipe.begin(), recipe.end(), 'B');
    ll numS = count(recipe.begin(), recipe.end(), 'S');
    ll numC = count(recipe.begin(), recipe.end(), 'C');

    auto canMake = [&](ll amount) {
        i128 needB = max<i128>((i128)numB * amount - nb, 0);
        i128 needS = max<i128>((i128)numS * amount - ns, 0);
        i128 needC = max<i128>((i128)numC * amount - nc, 0);

        return needB * pb + needS * ps + needC * pc <= r;
    };

    ll left = 0, right = 1;
    while (canMake(right)) {
        right *= 2;
    }

    while (left < right) {
        ll mid = left + (right - left + 1) / 2;
        if (canMake(mid)) {
            left = mid;
        } else {
            right = mid - 1;
        }
    }

    cout << left << '\n';
    return 0;
}

